import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("0.00")
        return

    idx = 0
    R = int(data[idx])
    C = int(data[idx+1])
    idx += 2

    gates = []
    for _ in range(3):
        r = int(data[idx]) - 1
        c = int(data[idx+1]) - 1
        gates.append((r, c))
        idx += 2

    cage_r = int(data[idx]) - 1
    cage_c = int(data[idx+1]) - 1
    idx += 2

    grid = []
    for _ in range(R):
        row = data[idx:idx+C]
        grid.append(row)
        idx += C

    total_grasslands = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'G':
                total_grasslands += 1

    if total_grasslands == 0:
        print("0.00")
        return

    # Distance from each grassland to nearest gate (person can reach)
    person_dist = [[-1] * C for _ in range(R)]
    q = deque()

    for gate_r, gate_c in gates:
        if 0 <= gate_r < R and 0 <= gate_c < C and grid[gate_r][gate_c] == 'G':
            person_dist[gate_r][gate_c] = 0
            q.append((gate_r, gate_c))

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 'G' and person_dist[nr][nc] == -1:
                person_dist[nr][nc] = person_dist[r][c] + 1
                q.append((nr, nc))

    # Distance from cage to all reachable areas (t-rex can move on G and M)
    t_rex_dist = [[-1] * C for _ in range(R)]
    q = deque()

    if 0 <= cage_r < R and 0 <= cage_c < C and grid[cage_r][cage_c] in ['G', 'M']:
        t_rex_dist[cage_r][cage_c] = 0
        q.append((cage_r, cage_c))

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] in ['G', 'M'] and t_rex_dist[nr][nc] == -1:
                t_rex_dist[nr][nc] = t_rex_dist[r][c] + 1
                q.append((nr, nc))

    safe_count = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'G':
                # Grassland is safe if:
                # 1. Person cannot reach it, OR
                # 2. Person can reach some gate faster than t-rex can reach that gate
                if person_dist[r][c] == -1:
                    safe_count += 1
                else:
                    # Find minimum distance to any gate for person
                    min_person_dist = person_dist[r][c]
                    # Find minimum distance to any gate for t-rex
                    min_t_rex_dist = float('inf')
                    for gate_r, gate_c in gates:
                        if 0 <= gate_r < R and 0 <= gate_c < C and t_rex_dist[gate_r][gate_c] != -1:
                            min_t_rex_dist = min(min_t_rex_dist, t_rex_dist[gate_r][gate_c])

                    if min_t_rex_dist == float('inf'):
                        # T-rex cannot reach any gate, so grassland is safe
                        safe_count += 1
                    else:
                        # Person needs to travel from grassland to gate
                        # Total time for person = distance_to_gate + distance_from_grassland_to_gate
                        # We need to find if there exists a gate where:
                        # person_time < t_rex_time_to_gate
                        is_safe = False
                        for gate_r, gate_c in gates:
                            if 0 <= gate_r < R and 0 <= gate_c < C:
                                if person_dist[gate_r][gate_c] != -1 and t_rex_dist[gate_r][gate_c] != -1:
                                    person_time = person_dist[gate_r][gate_c]
                                    t_rex_time = t_rex_dist[gate_r][gate_c]
                                    if person_time < t_rex_time:
                                        is_safe = True
                                        break
                        if is_safe:
                            safe_count += 1

    safety_index = (safe_count * 100) / total_grasslands
    print("{:.2f}".format(safety_index))

if __name__ == "__main__":
    main()
